import numpy as np

def mahalanobis(x, mu, Sigma):
    """Distance of x from mu in the coordinates where the cloud is round."""
    d = np.asarray(x, dtype=float) - np.asarray(mu, dtype=float)
    w = np.linalg.solve(np.asarray(Sigma, dtype=float), d)
    return float(np.sqrt(d @ w))
